from dataclasses import FrozenInstanceError
from decimal import Decimal

import pytest

from payment.domain.money import Money


def test_the_currency_is_normalised_to_upper_case() -> None:
    assert Money(Decimal("1"), "eur").currency == "EUR"


@pytest.mark.parametrize("amount", ["0", "-1", "-0.01", "0.5", "1"])
def test_only_positive_amounts_are_rejected_when_not_positive(amount: str) -> None:
    if Decimal(amount) <= 0:
        with pytest.raises(ValueError, match="positive"):
            Money(Decimal(amount), "EUR")
    else:
        assert Money(Decimal(amount), "EUR").amount == Decimal(amount)


@pytest.mark.parametrize("currency", ["", "   "])
def test_a_blank_currency_is_rejected(currency: str) -> None:
    with pytest.raises(ValueError, match="currency"):
        Money(Decimal("1"), currency)


def test_money_is_immutable() -> None:
    money = Money(Decimal("1"), "EUR")
    with pytest.raises(FrozenInstanceError):
        money.amount = Decimal("2")  # type: ignore[misc]
EOF
cat >> tests/unit/test_authorize_payment.py <<'EOF'


def test_the_receipt_records_amount_currency_and_outcome() -> None:
    receipts = InMemoryReceiptStore()
    handler = AuthorizePayment(AlwaysAnswers(AuthorizationOutcome.DECLINED), receipts)

    handler.handle("ORD-3", Money(Decimal("10.5"), "eur"))

    assert receipts.saved == {"ORD-3": "EUR 10.5 -> DECLINED"}


def test_the_handler_is_not_meant_to_be_subclassed() -> None:
    assert AuthorizePayment.__final__ is True
EOF
